let lit s =
  let b = Buffer.create (String.length s + 2) in
  Buffer.add_char b '"';
  String.iter (fun c ->
    match c with
    | '"' -> Buffer.add_string b "\\\""
    | '\\' -> Buffer.add_string b "\\\\"
    | '\n' -> Buffer.add_string b "\\n"
    | '\t' -> Buffer.add_string b "\\t"
    | '\r' -> Buffer.add_string b "\\r"
    | c when c < ' ' || c = '\x7f' -> Printf.bprintf b "\\%03d" (Char.code c)
    | c -> Buffer.add_char b c) s;
  Buffer.add_char b '"';
  Buffer.contents b

let read path =
  let ic = open_in_bin path in
  Fun.protect ~finally:(fun () -> close_in_noerr ic) (fun () ->
    really_input_string ic (in_channel_length ic))

let () =
  match Sys.argv with
  | [| _; katex; metrics; layout; out |] ->
      let oc = open_out_bin out in
      Printf.fprintf oc "(* generated by tools/katex_gen.exe — do not edit *)\n";
      Printf.fprintf oc "let katex_js = %s\n\nlet metrics_js = %s\n\nlet layout_js = %s\n"
        (lit (read katex)) (lit (read metrics)) (lit (read layout));
      close_out oc
  | _ -> prerr_endline "usage: katex_gen <katex.min.js> <font_metrics.js> <layout.js> <out.ml>"; exit 1
